Rewrite the following GNU C++17 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to rewrite:
<original_code>
// In the name of God

#include<bits/stdc++.h>

#define F first
#define S second
#define PB push_back
#define sz(s) int((s).size())
#define bit(n,k) (((n)>>(k))&1)

using namespace std;

typedef long long ll;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;
typedef unsigned int ui;

const int Lg=18,Tw=(1<<Lg),Max=Tw+10;

int Ans[Max][Lg+3],tmp[Lg+3],tmp2[Lg+3],fac[Max],ifac[Max],N,n,mod=1e9+7;

int Pow(int a,int b){
    int ans=1;
    while(b){
	if(b&1) ans=1ll*ans*a %mod;
	a=1ll*a*a %mod;
	b>>=1;
    }
    return ans;
}
inline void Add(int *a,int *b){
    for(int i=0;i<=N;i++)
	a[i]=(a[i]+b[i])%mod;
}
inline void Sub(int *a,int *b){
    for(int i=0;i<=N;i++)
	a[i]=(a[i]-b[i])%mod;
}
inline void Mul(int *ans,int *a,int *b){
    memset(tmp,0,sizeof tmp);
    for(int i=0;i<=N;i++){
	for(int j=0;j<=i;j++){
	    tmp[i]=(1ll*tmp[i]+1ll*a[j]*b[i-j])%mod;
	}
    }
    memcpy(ans,tmp,sizeof tmp);
}
void trans1(int a[][Lg+3]){
    for(int i=0;i<N;i++)
	for(int msk=n;msk>=0;msk--)
	    if(bit(msk,i))
		Add(a[msk],a[msk ^ (1<<i)]);
}
void trans2(int a[][Lg+3]){
    for(int i=0;i<N;i++)
	for(int msk=n;msk>=0;msk--)
	    if(bit(msk,i))
		Sub(a[msk],a[msk ^ (1<<i)]);
}

vector<int>vec;

int main(){
    int K;cin>>n>>K>>mod;
    int ANS=Pow(K,n);
    if(n&1) return cout<<ANS<<endl,0;
    N=__builtin_popcount(n);
    int Nbef=n;
    for(int i=0;i<Lg;i++){
	if(bit(n,i))
	    vec.PB(i);
    }
    n=(1<<N)-1;
    fac[0]=1;
    for(int i=1;i<Max;i++)
	fac[i]=1ll*i*fac[i-1]%mod;
    ifac[Max-1]=Pow(fac[Max-1],mod-2);
    for(int i=Max-2;i>=0;i--)
	ifac[i]=1ll*(i+1)*ifac[i+1] %mod;
    for(int i=0;i<=n;i++){
	int Real=0;
	for(int j=0;j<N;j++)
	    Real+=bit(i,j)*(1<<vec[j]);
	Ans[i][__builtin_popcount(i)]=ifac[Real];
    }
    trans1(Ans);
    for(int i=0;i<=n;i++){
	int KK=K;
	memset(tmp2,0,sizeof tmp2); tmp2[0]=1;

	while(KK){
	    if(KK&1) Mul(tmp2,tmp2,Ans[i]);
	    Mul(Ans[i],Ans[i],Ans[i]);
	    KK>>=1;
	}
	memcpy(Ans[i],tmp2,sizeof tmp2);
    }
    trans2(Ans);
    ANS=(1ll*ANS-1ll*Ans[n][N]*fac[Nbef])%mod;
    if(ANS<0) ANS+=mod;	
    return cout<<ANS<<endl,0;
}

</original_code>
